const today = DEMO_TODAY;
const isErrorMessage = (message: string) => /^(error|no se pudo|no pod|complet|ingres|seleccion|el nombre es|ya existe)|inválid|no válid/i.test(message);
const PDF_SIZE_HELP = 'Máximo 5 MB';
const OPEN_ORDER_EXCLUDED = new Set(['Recibido', 'Recibido OK', 'Cerrado', 'Cancelado']);
const isOpenOrder = (order: Order) => !OPEN_ORDER_EXCLUDED.has(order.status);
const EMAIL_PATTERN = /^\S+@\S+\.\S+$/;
const dateEs = (value: string) => value ? formatDateEs(value) : 'Pendiente';
const requesterLabel = (order: Order) => order.requester ? order.requester : order.responsible ? `Legacy · responsable (${order.responsible})` : 'Legacy / no registrado';
const requestedAtLabel = (order: Order) => order.requestedAt ? `${dateEs(order.requestedAt)} · ${order.requestedAt.slice(11, 16)}` : order.createdAt ? `Legacy · creación (${dateEs(order.createdAt)})` : 'Legacy / no registrado';
const supplierName = (suppliers: Supplier[], id: string) => suppliers.find((x) => x.id === id)?.name || 'Sin proveedor';
const orderTotal = (order: Order) => order.lines.reduce((sum, line) => sum + line.price * line.quantity, 0);
const paymentMethods: PaymentMethod[] = ['efectivo', 'transferencia', 'tarjeta', 'cuenta corriente'];
const paymentStatuses: PaymentStatus[] = ['pendiente', 'parcial', 'pagado', 'vencido'];

const receptionLabels: Record<ReceptionStatus, string> = { pending: 'Pendiente', received: 'Llegó', shortage: 'Faltante', surplus: 'Sobrante', substitution: 'Sustitución' };
const roles: UserRole[] = ['Administrador', 'Compras', 'Recepción', 'Consulta'];
type State = DemoState;
