    <div className="mb-6 grid grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-4"><Metric title="Pagado" value={money(totals.paid)} note="Pagos confirmados" color="green" /><Metric title="Pendiente" value={money(totals.pending)} note="Pendiente y parcial" color="amber" /><Metric title="Vencido" value={money(totals.overdue)} note="Requiere gestión" color="red" /></div>
